function summarize(orders) {
  const valid = orders.filter((o) => o.status === 'paid');
  const totals = valid.map((o) => o.items.reduce((s, i) => s + i.price * i.qty, 0));
  const gross = totals.reduce((s, t) => s + t, 0);
  const fees = totals.map((t) => Math.round(t * 0.029 * 100) / 100);
  const net = gross - fees.reduce((s, f) => s + f, 0);
  return { count: valid.length, gross, net };
}

module.exports = { summarize };

